from __future__ import annotations

from typing import Any


class FakeDbGateway:
    def __init__(self) -> None:
        self._users: list[dict[str, Any]] = []
        self._last_query = ""

    def seed_users(self, users: list[dict[str, Any]]) -> None:
        self._users = []
        for user in users:
            self._users.append(
                {
                    "id": int(user.get("id", 0)),
                    "email": str(user.get("email", "")).strip().lower(),
                    "name": str(user.get("name", "")).strip(),
                    "role": str(user.get("role", "user")).strip().lower(),
                }
            )

    def execute_raw_query(self, sql: str) -> list[dict[str, Any]]:
        query = sql.strip()
        self._last_query = query

        normalized = query.lower()
        if "where" not in normalized:
            return [dict(user) for user in self._users]

        # Intentionally simplistic parser for challenge simulation.
        if "or '1'='1" in normalized or 'or "1"="1' in normalized:
            return [dict(user) for user in self._users]

        marker = "like '%"
        start = normalized.find(marker)
        if start < 0:
            return []
        start += len(marker)
        end = normalized.find("%'", start)
        if end < 0:
            return []
        term = normalized[start:end]

        return [
            dict(user)
            for user in self._users
            if term in str(user["email"]).lower() or term in str(user["name"]).lower()
        ]

    def execute_parameterized_search(self, term: str) -> list[dict[str, Any]]:
        safe = term.strip().lower()
        if not safe:
            return []
        return [
            dict(user)
            for user in self._users
            if safe in str(user["email"]).lower() or safe in str(user["name"]).lower()
        ]

    def count(self) -> int:
        return len(self._users)

    def last_query(self) -> str:
        return self._last_query

    def clear(self) -> None:
        self._users.clear()
        self._last_query = ""

