from __future__ import annotations

from typing import Any

from db_gateway import FakeDbGateway


def search_users(payload: dict[str, Any], db: FakeDbGateway) -> dict[str, Any]:
    search = str(payload.get("search", "")).strip()
    include_admins = bool(payload.get("include_admins", False))
    limit = int(payload.get("limit", 20))

    if limit <= 0:
        return {"ok": False, "reason": "invalid_limit", "items": []}
    if limit > 100:
        return {"ok": False, "reason": "limit_too_large", "items": []}
    if not search:
        return {"ok": True, "reason": "ok", "items": []}

    # Bug: string concatenation opens query to injection.
    sql = (
        "SELECT id, email, name, role FROM users "
        f"WHERE email LIKE '%{search}%' OR name LIKE '%{search}%'"
    )
    rows = db.execute_raw_query(sql)

    if not include_admins:
        rows = [row for row in rows if str(row.get("role", "")).lower() != "admin"]

    rows = rows[:limit]
    return {
        "ok": True,
        "reason": "ok",
        "items": rows,
        "count": len(rows),
    }


def search_users_for_api(payload: dict[str, Any], db: FakeDbGateway) -> dict[str, Any]:
    result = search_users(payload, db)
    if result.get("ok"):
        return {"status": 200, "body": result}
    return {"status": 400, "body": result}


def search_batch(payloads: list[dict[str, Any]], db: FakeDbGateway) -> dict[str, Any]:
    outputs: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        out = search_users(payload, db)
        outputs.append(out)
        if out.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "outputs": outputs}

